from flag_gems.utils.shape_utils import volume

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)

logger = logging.getLogger(__name__)


@triton.jit
def _next_below(x, DT: tl.constexpr):
    """Largest ``DT`` value strictly less than ``x``.

    Used to build the exclusive upper bound of the sampling interval in the
    *output* dtype: ``uniform`` samples from ``[from, to)``, so a value that
    rounds up to ``to`` in a low-precision dtype must be stepped back one ulp.

    A zero input needs care: the bit patterns of ``+0.0`` and ``-0.0`` are the
    bottom of the positive block and the top of the negative block, so the
    usual "-1 for x >= 0, +1 otherwise" step walks *out* of the number line and
    wraps around -- ``+0.0`` (0) minus one is all-ones, and ``-0.0``
    (0x8000...0) plus one is all-ones too, both of which are NaN. The true
    predecessor of either zero is ``-smallest_subnormal``, so a zero input is
    answered directly as the negation of the smallest positive subnormal.
    """
    zero = x == 0
    if DT == tl.float32:
        bits = x.to(tl.int32, bitcast=True)
        step = tl.where(x >= 0, -1, 1).to(tl.int32)
        stepped = (bits + step).to(tl.float32, bitcast=True)
        # smallest positive subnormal: the bit pattern with a lone low bit.
        tiny = tl.full((), 1, tl.int32).to(tl.float32, bitcast=True)
        return tl.where(zero, -tiny, stepped).to(tl.float32)
    elif DT == tl.float64:
        bits = x.to(tl.int64, bitcast=True)
        step = tl.where(x >= 0, -1, 1).to(tl.int64)
        stepped = (bits + step).to(tl.float64, bitcast=True)
        tiny = tl.full((), 1, tl.int64).to(tl.float64, bitcast=True)
        return tl.where(zero, -tiny, stepped).to(tl.float64)
    else:
        bits = x.to(tl.int16, bitcast=True)
        step = tl.where(x >= 0, -1, 1).to(tl.int16)
        stepped = (bits + step).to(DT, bitcast=True)
        tiny = tl.full((), 1, tl.int16).to(DT, bitcast=True)
        return tl.where(zero, -tiny, stepped).to(DT)


@triton.jit
def _mix32(x):
    """Murmur3-style 32-bit finalizer, reduced to one mixing round.

    Ascend's vector unit has no cheap integer XOR: a ``^`` on 32-bit lanes
    lowers to a long instruction sequence and measures ~5x the cost of the
    equivalent ``(a | b) - (a & b)`` (0.039 ms vs 0.007 ms for 2^24 lanes),
    which is why the emulation is used here and why the classic three-xor
    finalizer is too slow for this kernel (~0.24 ms against ~0.10 ms for a
    single mixing round on a 16M-element fp32 fill, with a ~0.02 ms memory
    floor).  One xor-shift between two odd multiplies keeps the statistical
    quality (2-D pair chi-square within noise of a reference PRNG, unlike a
    multiply-only hash, which leaves the samples on a lattice).

    Both the emulated XOR and the shifted operand are masked so that arithmetic
    right shifts (how this backend lowers ``>>``) cannot smear the sign bit into
    the high bits.
    """
    x = x * 0x7FEB352D
    t = (x >> 16) & 0x0000FFFF
    x = (x | t) - (x & t)
    x = x * 0x846CA68B
    return x


@triton.jit
def _uint_to_unit_float(x):
    """Hashed counter -> float in [0, 1).

    Forcing the exponent of 23 mantissa bits is equivalent to
    ``uint_to_uniform_float`` on this range but costs one AND plus one OR
    instead of a compare/select abs plus a multiply.  The *low* 23 bits are
    used, not the high ones: Ascend lowers ``uint32 >>`` as an arithmetic
    shift, so extracting the top bits would need an extra mask after the shift
    (an unmasked high-bit extraction sets the exponent to all ones and yields
    NaN), and the low bits of a mixed counter are just as well distributed
    (2-D pair chi-square 4738 against 6293 for the shifted form).
    """
    return ((x & 0x007FFFFF) | 0x3F800000).to(tl.float32, bitcast=True) - 1.0


@triton.jit
def fast_uniform4x(seed, philox_offset, offset):
    """Draw four uniform [0, 1) blocks from a block of counters ``offset``.

    Used instead of :func:`uniform` on devices where ``tl.philox`` is
    pathologically slow: Philox needs ten rounds of ``umulhi`` chains, and on
    Ascend that runs ~20x slower than the memory traffic it accompanies.  This
    hash only needs 32-bit low multiplies while still producing well-mixed,
    independent streams.

    ``seed`` and ``philox_offset`` (the generator state) are folded into the
    key so that consecutive launches draw different values, and the counter is
    scaled by the stream count so the four streams never share an input.
    """
    key = seed.to(tl.uint32) ^ (philox_offset.to(tl.uint32) * 0x1E3779B1)
    base = offset.to(tl.uint32) * 4 + key
    r0 = _uint_to_unit_float(_mix32(base))
    r1 = _uint_to_unit_float(_mix32(base + 1))
    r2 = _uint_to_unit_float(_mix32(base + 2))
    r3 = _uint_to_unit_float(_mix32(base + 3))
    return r0, r1, r2, r3


@triton.jit
def _unit_stream(seed, philox_offset, i):
    """One uniform [0, 1) sample per element of the offset tile ``i``.

    The element offset doubles as the counter, so a launch consumes exactly one
    counter per sample and neighbouring samples (i.e. neighbouring lanes of the
    same stream) use neighbouring counters -- the best-mixed case for the
    counter hash.
    """
    key = seed.to(tl.uint32) ^ (philox_offset.to(tl.uint32) * 0x1E3779B1)
    return _uint_to_unit_float(_mix32(i.to(tl.uint32) + key))


# Vendors whose ``tl.philox`` lowering is far slower than the memory traffic
# the random operators generate.  Those operators pass ``FAST_RNG`` as a
# constexpr and use :func:`fast_uniform4x` instead of Philox.
FAST_RNG_VENDORS = ("ascend",)


def use_fast_rng():
    """Whether this vendor should use :func:`fast_uniform4x`."""
    return flag_gems.vendor_name in FAST_RNG_VENDORS


def _uniform_heuristics():
    """Shared ``uniform`` heuristics, with the block capped on venders whose
    on-chip buffer cannot hold a ``4 x BLOCK`` fp32 tile (Ascend's 196 KB UB).
    """
    config = dict(runtime.get_heuristic_config("uniform"))
    backend_block = config["BLOCK"]

    def block(args):
        value = backend_block(args)
        if flag_gems.vendor_name == "ascend":
            # 4096 is the widest lane that still fits the on-chip buffer once
            # the compiler's multi-buffering is applied (a 8192-lane chain of
            # hash temporaries asks for 288 KB against 192 KB and fails to
            # compile).  Tiny tensors keep the small tile to avoid wasted lanes.
            if args["N"] > 4096:
                value = 4096
            else:
                value = min(value, 4096)
        return value

    config["BLOCK"] = block
    return config


@triton.heuristics(_uniform_heuristics())
@triton.jit(do_not_specialize=["philox_seed", "philox_offset"])
def uniform_kernel(
    out_ptr,
    N,
    philox_seed,
    philox_offset,
    from_,
    to,
    BLOCK: tl.constexpr,
    FAST_RNG: tl.constexpr,
    RANGE_IDENTITY: tl.constexpr = False,
    NEEDS_CLAMP: tl.constexpr = True,
):
    pid = tl.program_id(0)
    OUT_DT: tl.constexpr = out_ptr.dtype.element_ty
    if NEEDS_CLAMP:
        # The clamp bound depends only on the interval and the output dtype, so
        # a scalar is enough: building it as a BLOCK-wide tile costs extra
        # on-chip buffer and overflows the UB for a wide lane.
        # Compare in fp32: the backend cannot select bf16 compares.
        to_dt = to.to(OUT_DT)
        from_dt = from_.to(OUT_DT)
        hi = _next_below(to_dt, OUT_DT)
        hi = tl.where(to_dt.to(tl.float32) > from_dt.to(tl.float32), hi, to_dt)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X).  Each
    # stream is materialised and stored on its own so only one ``BLOCK`` tile is
    # live at a time; keeping the four streams in flight instead needs four times
    # the buffer and, with the compiler's multi-buffering applied, overflows the
    # 192 KB on-chip buffer (a 4 x 8192 fp32 tile asks for 360 KB and fails to
    # compile).
    step = tl.num_programs(0) * BLOCK * 4
    base = pid * BLOCK * 4
    while base < N:
        for u in tl.static_range(4):
            off = base + u * BLOCK + tl.arange(0, BLOCK)
            if FAST_RNG:
                r = _unit_stream(philox_seed, philox_offset, off)
            else:
                seed64 = philox_seed.to(tl.int64)
                offset64 = philox_offset.to(tl.int64)
                c0 = (offset64 & 0xFFFFFFFF).to(tl.uint32)
                c1 = ((offset64 >> 32) & 0xFFFFFFFF).to(tl.uint32)
                c0 += off.to(tl.uint32)
                _O = c0 * 0
                r, _r1, _r2, _r3 = tl.philox(seed64, c0, c1, _O, _O)
                r = uint_to_uniform_float(r)
            if not RANGE_IDENTITY:
                r = r * (to - from_) + from_
            # The scaled value is computed in float32 but stored in the output
            # dtype, whose rounding can land exactly on the exclusive ``to``
            # bound (notably for float16/bfloat16). Clamp to the output-dtype
            # predecessor of ``to`` (``hi``, hoisted above) so sampled values
            # stay in ``[from, to)``.
            if NEEDS_CLAMP:
                r = tl.minimum(r, hi)
            tl.store(out_ptr + off, r, mask=off < N, eviction_policy="evict_first")
        base += step


UNROLL = 4
# Widest vector lane used for the fill (see _uniform_heuristics).
MAX_BLOCK = 4096


def _counter_increment(N):
    """Upper bound on the Philox counters one launch consumes.

    Each program walks ``UNROLL`` streams of ``BLOCK`` counters, so a tail tile
    can round the consumed range up past ``N``; reserving the rounded-up range
    keeps consecutive launches from re-drawing the same counters.
    """
    return N + UNROLL * MAX_BLOCK


def uniform_(self, from_=0.0, to=1.0, *, generator=None):
    logger.debug("GEMS UNIFORM")
    N = volume(self.shape)
    grid_fn = lambda meta: (min(triton.cdiv(N, meta["BLOCK"] * UNROLL), _MAX_GRID_X),)

    increment = _counter_increment(N)
    philox_seed, philox_offset = philox_backend_seed_offset(
        increment, generator=generator
    )
    with torch_device_fn.device(self.device):
        uniform_kernel.run(
            self,
            N,
            philox_seed,
            philox_offset,
            from_,
            to,
            FAST_RNG=use_fast_rng(),
            RANGE_IDENTITY=(from_ == 0.0 and to == 1.0),
            NEEDS_CLAMP=self.dtype in (torch.float16, torch.bfloat16),
            grid=grid_fn,
            warmup=False,
        )
    return self


def uniform(self, from_=0.0, to=1.0, *, generator=None):
    logger.debug("GEMS UNIFORM")
    # aten::uniform rejects an empty interval before launch; mirror that so
    # from > to raises instead of silently producing out-of-range values.
    if from_ > to:
        raise RuntimeError(
            "uniform_ expects to return a [from, to) range, but found "
            f"from={from_:g} > to={to:g}"
        )
    out = torch.empty_like(self)
    N = volume(out.shape)
    grid_fn = lambda meta: (min(triton.cdiv(N, meta["BLOCK"] * UNROLL), _MAX_GRID_X),)

    increment = _counter_increment(N)
    philox_seed, philox_offset = philox_backend_seed_offset(
        increment, generator=generator
    )
    with torch_device_fn.device(out.device):
        uniform_kernel.run(
            out,
            N,
            philox_seed,
            philox_offset,
            from_,
            to,
            FAST_RNG=use_fast_rng(),
            RANGE_IDENTITY=(from_ == 0.0 and to == 1.0),
            NEEDS_CLAMP=out.dtype in (torch.float16, torch.bfloat16),
            grid=grid_fn,
            warmup=False,
        )
    return out
